def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Count colors
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    if len(counts) < 2:
        return [row[:] for row in grid]

    # Larger-count nonzero color is the main object, smaller-count color is the scattered marker color
    colors = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    obj_color = colors[0][0]
    mark_color = colors[-1][0]

    # Bounding box of the main object
    obj_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    min_r = min(r for r, c in obj_cells)
    max_r = max(r for r, c in obj_cells)
    min_c = min(c for r, c in obj_cells)
    max_c = max(c for r, c in obj_cells)

    out = [row[:] for row in grid]

    # Select columns inside the object's bbox that contain at least one marker below the object
    for c in range(min_c, max_c + 1):
        has_marker_below = any(grid[r][c] == mark_color for r in range(max_r + 1, h))
        if not has_marker_below:
            continue

        # Find the lowest object cell in this column within the bbox
        lowest_obj = None
        for r in range(max_r, min_r - 1, -1):
            if grid[r][c] == obj_color:
                lowest_obj = r
                break

        if lowest_obj is None:
            continue

        # Draw the vertical marker line below that lowest object cell
        for r in range(lowest_obj + 1, h):
            if out[r][c] == 0:
                out[r][c] = mark_color

    return out

